import warnings,time
warnings.filterwarnings('ignore')
import numpy as np,pandas as pd
from sklearn.model_selection import RepeatedKFold
from sklearn.ensemble import ExtraTreesRegressor
from sklearn.svm import SVR
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import StandardScaler
from sklearn.compose import TransformedTargetRegressor
from sklearn.gaussian_process import GaussianProcessRegressor
from sklearn.gaussian_process.kernels import ConstantKernel,RationalQuadratic,WhiteKernel
from sklearn.metrics import mean_squared_error,mean_absolute_error
from scipy.stats import spearmanr
from sklearn.base import clone
tr=pd.read_csv('b3_te_dopant_train.csv');po=pd.read_csv('b3_te_dopant_pool.csv');X=tr[['Sb','Co','Fe']].to_numpy();P=po[['Sb','Co','Fe']].to_numpy();y=tr.target.to_numpy()
def physical(x):
 s,c,f=x.T
 return np.column_stack([1-s-c-f,s/(c+f),f/(c+f)])
views={'raw':(X,P),'phys':(physical(X),physical(P)),'aug':(np.column_stack([X,physical(X)]),np.column_stack([P,physical(P)]))}
models={}
for key,C,gamma in [('raw',3,10),('phys',1,10),('aug',3,3)]:
 models['SVR_'+key]=(key,TransformedTargetRegressor(regressor=make_pipeline(StandardScaler(),SVR(C=C,gamma=gamma,epsilon=.3)),transformer=StandardScaler()))
kernel=ConstantKernel(1,(.01,100))*RationalQuadratic(length_scale=1,alpha=1,length_scale_bounds=(.01,100),alpha_bounds=(.01,100))+WhiteKernel(.3,(1e-4,2))
models['GP']=('phys',make_pipeline(StandardScaler(),GaussianProcessRegressor(kernel=kernel,normalize_y=True,alpha=1e-10,n_restarts_optimizer=1,random_state=42)))
for leaf in [2,4]:models[f'ET{leaf}']=('aug',ExtraTreesRegressor(n_estimators=400,min_samples_leaf=leaf,max_features=1.,random_state=42,n_jobs=1))
full={};scores={}
ensembles={'SVRs':['SVR_raw','SVR_phys','SVR_aug'],'smooth':['SVR_raw','SVR_phys','SVR_aug','GP'],'smooth_ET2':['SVR_raw','SVR_phys','SVR_aug','GP','ET2'],'all':['SVR_raw','SVR_phys','SVR_aug','GP','ET2','ET4'],'SVRs_ET2':['SVR_raw','SVR_phys','SVR_aug','ET2']}
for seed in [42,137]:
 cv=list(RepeatedKFold(n_splits=5,n_repeats=3 if seed==137 else 2,random_state=seed).split(X,y));truth=np.concatenate([y[b] for a,b in cv]);oof={};fits={}
 for name,(key,m) in models.items():
  xx,pp=views[key];vv=[];pv=[]
  for a,b in cv:
   fitted=clone(m).fit(xx[a],y[a]);vv.append(fitted.predict(xx[b]));pv.append(fitted.predict(pp))
  oof[name]=np.concatenate(vv);fits[name]=np.array(pv)
  if seed==42:full[name]=m.fit(xx,y).predict(pp)
  print('seed',seed,name,'RMSE',round(np.sqrt(mean_squared_error(truth,oof[name])),4),'MAE',round(mean_absolute_error(truth,oof[name]),4),'Spearman',round(spearmanr(truth,oof[name]).statistic,4),flush=True)
 for en,names in ensembles.items():
  pred=np.mean([oof[n] for n in names],axis=0);pc=np.mean([full[n] for n in names],axis=0);pf=np.mean([fits[n] for n in names],axis=0)
  top_observed=np.mean([truth[sum(len(b) for a,b in cv[:k])+np.argsort(pred[sum(len(b) for a,b in cv[:k]):sum(len(b) for a,b in cv[:k+1])])[-5:]].mean() for k in range(len(cv))])
  print('seed',seed,en,'RMSE',round(np.sqrt(mean_squared_error(truth,pred)),4),'MAE',round(mean_absolute_error(truth,pred),4),'Spearman',round(spearmanr(truth,pred).statistic,4),'top5_actual',round(top_observed,4),'TOP',', '.join(f'{po.candidate_id[i]}:{pc[i]:.3f}' for i in np.argsort(pc)[-10:][::-1]),flush=True)
  if en=='all' and seed==137:
   out=po.copy();out['pred']=pc;out['refit_sd']=pf.std(axis=0);out['refit_mean']=pf.mean(axis=0);out['top5_freq']=(np.argsort(np.argsort(-pf,axis=1),axis=1)<5).mean(axis=0)
   for key in full:out[key]=full[key]
   print('FINAL CANDIDATE DETAILS\n',out.nlargest(20,'pred').to_string(index=False))
